from typing import List

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        min_left = []
        min_right = []
        ml = float('inf')
        mr = float('inf')
        ans = float('inf')

        for i in range(len(nums) - 1):
            if nums[i] < ml:
                ml = nums[i]
            min_left.append(ml)

        for i in range(len(nums) - 1, 0, -1):
            if nums[i] < mr:
                mr = nums[i]
            min_right.append(mr)

        min_right.reverse()

        for i in range(1, len(nums) - 1):
            if ans == float('inf'):
                return -1

            ml = min_left[i - 1]
            mr = min_right[i - 1]

            if ml < nums[i] and nums[i] > mr:
                ans = min(ans, nums[i] + ml + mr)

        return ans if ans != float('inf') else -1

